python3 - <<'EOF'
import pathlib, re
pat = re.compile(r"(?:filterwarnings|simplefilter)\(\s*['\"]ignore['\"]\s*\)")
n = 0
for p in sorted(pathlib.Path("src").glob("*.py")) + sorted(pathlib.Path("src/utils").glob("*.py")):
    for line in p.read_text(encoding="utf-8").splitlines():
        s = line.strip()
        if s.startswith("#"):
            continue
        if pat.search(s):
            n += 1
print(n)
EOF
